    if not texto.strip():
        raise ValueError('no puede estar vacío')
    return texto.strip()


Texto = Annotated[str, AfterValidator(_no_vacio)]


class NuevaSerie(BaseModel):
    nombre: Texto
    instructor: Texto
    dia: Literal['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo']
    hora: str = Field(pattern=HORA)
    duracion_min: int = Field(ge=1)
    cupo: int = Field(ge=1)
    desde: date
    hasta: date

    @model_validator(mode='after')
    def rango_de_fechas(self):
        if self.hasta < self.desde:
            raise ValueError('hasta es anterior a desde')
        if (self.hasta - self.desde).days > 366:
            raise ValueError('la serie no puede durar más de 366 días')
        return self


def _inicios_de(datos: NuevaSerie):
    """Inicio de cada clase de la serie: un día de la semana por semana, sin cierres ni pasado."""
    ahora = reloj.ahora()
    indice = DIAS.index(datos.dia)
    inicios = []
    dia = datos.desde
    while dia <= datos.hasta:
        if dia.weekday() == indice and dia not in CERRADOS:
            inicio = con_hora(datetime(dia.year, dia.month, dia.day, tzinfo=reloj.MONTEVIDEO), datos.hora)
            if inicio > ahora:
                inicios.append(inicio)
        dia += timedelta(days=1)
    return inicios


@router.post('/admin/series', status_code=201, dependencies=[Depends(admin)])
def crear_serie(datos: NuevaSerie):
    inicios = _inicios_de(datos)
    serie_id = db.crear_serie(dict(datos.model_dump(), desde=datos.desde.isoformat(), hasta=datos.hasta.isoformat()),
                              inicios)
    return ver_serie(db.serie(serie_id))


